/* Planned food editing and conversion of actual workouts, scoped to the current profile. */
function recalculateFoodPlan(plan){for(const day of plan.days){for(const meal of day.meals)Object.assign(meal,foodTotal(meal.items));Object.assign(day,foodTotal(day.meals.flatMap(m=>m.items)))}return plan}
function installLightDinner(){if(!window.fitnessAccount?.owner||activeProfile!=='default'||!data.nutrition.plan||data.nutrition.plan.lightDinnerVersion)return;const next=structuredClone(data),plan=next.nutrition.plan;next.nutrition.previousDinnerPlan=structuredClone(plan);for(const [i,day] of plan.days.entries())for(const meal of day.meals)if(meal.name==='عشاء')meal.items=lightDinnerItems(next.nutrition.intake?.excluded||[],i);plan.lightDinnerVersion=1;plan.manuallyAdjusted=true;recalculateFoodPlan(plan);validate(next);commit(next,'تم تحديث العشاء لخيارات خفيفة جاهزة للأكل؛ راجع إجمالي اليوم')}
function workoutAsPlan(w){const session=sessionForDate(w.date),existing=(data.training.exercises||[]).find(x=>x.session===session&&x.exercise.trim().toLowerCase()===w.exercise.trim().toLowerCase()),counts=(w.sets||[]).map(x=>Number(x.r)).filter(Number.isFinite);return {...existing,exercise:w.exercise,group:w.group,session,sets:Math.min(4,Math.max(1,w.sets?.length||3)),reps:counts.length?(Math.min(...counts)===Math.max(...counts)?String(counts[0]):Math.min(...counts)+'–'+Math.max(...counts)):'8–12',weight:existing?.weight??'',alternative:existing?.alternative||'',notes:existing?.notes||'من أداء '+pretty(w.date)+'. اختر الحمل عند تسجيل الجلسة القادمة.'}}
document.addEventListener('click',e=>{const id=e.target.closest('[data-record-plan]')?.dataset.recordPlan;if(id){const w=data.workouts.find(x=>x.id===id);if(w)editPlannedExercise(workoutAsPlan(w))}if(e.target.closest('[data-plan-records]')){const rows=byDate('workouts').filter(w=>w.exerciseType!=='كارديو');if(!rows.length){notify('لا توجد تمارين مقاومة مسجلة في التاريخ المحدد.',true);return}if(!confirm('اعتماد التمارين المسجلة بتاريخ '+pretty(selected)+' بدل التمارين المخططة ليوم '+trainingDayName(sessionForDate(selected))+'؟ تبقى سجلات الأداء محفوظة.'))return;const next=structuredClone(data),session=sessionForDate(selected),unique=new Map();for(const w of rows)unique.set(w.exercise.trim().toLowerCase(),workoutAsPlan(w));next.training.exercises=[...(next.training.exercises||[]).filter(x=>x.session!==session),...[...unique.values()].map(x=>({...x,id:x.id||uid()}))];try{validate(next);commit(next,'تم اعتماد تمارين اليوم كخطة أسبوعية')}catch(err){notify(err.message,true)}}});
function displayedFoodPlan(){if(data.nutrition.plan)return {plan:data.nutrition.plan,saved:true};const report=currentBodyReport();if(!report)return {plan:null,error:'أضف قياس InBody أو بياناتك الأساسية لإنشاء الخطة.'};const draft=coachDraft(report);return {...draft,saved:false,report}}
const foodPlanDialog=document.createElement('dialog');foodPlanDialog.id='foodPlanDialog';foodPlanDialog.setAttribute('aria-label','تعديل مكونات الوجبة');document.body.append(foodPlanDialog);
let mealDraft=null;
function openMealEditor(di,mi){const result=displayedFoodPlan();if(!result.plan)return;if(!result.saved&&(!result.n.healthConfirmed||Date.parse(today())-Date.parse(result.report.date)>90*86400000)){notify('أكد معلوماتك واختر قياسًا حديثًا قبل حفظ الخطة.',true);openCoachSetup();return}mealDraft={di,mi,plan:structuredClone(result.plan),fingerprint:JSON.stringify(data.nutrition.plan||null),profile:activeProfile};paintMealEditor();foodPlanDialog.showModal()}
function paintMealEditor(){const m=mealDraft.plan.days[mealDraft.di].meals[mealDraft.mi],excluded=data.nutrition.intake?.excluded||[],allowed=Object.keys(foods).filter(k=>!foods[k][5].some(t=>excluded.includes(t)));foodPlanDialog.innerHTML=`<form id="mealPlanForm"><div class="dialog-head"><h2>تعديل ${esc(m.name)}</h2><button type="button" class="icon-button" data-food-edit="close" aria-label="إغلاق">×</button></div><p class="sub">الكميات بالغرام للجزء المأكول. راجع الملصق الغذائي؛ القيم تقريبية.</p><div id="foodEditRows">${m.items.map((x,i)=>`<div class="food-edit-row"><label>الطعام<select data-food-key="${i}">${[...new Set([x.key,...allowed])].map(k=>`<option value="${k}" ${k===x.key?'selected':''}>${esc(foods[k][0])}${!allowed.includes(k)?' — ضمن الاستبعادات':''}</option>`).join('')}</select></label><label>الكمية (غ)<input type="number" min="1" max="2000" step="1" required value="${x.g}" data-food-grams="${i}"></label><button type="button" class="text-button danger" data-food-remove="${i}">حذف</button></div>`).join('')}</div><div class="quick-buttons"><button type="button" class="button secondary" data-food-edit="add">+ إضافة طعام</button>${m.name==='عشاء'?'<button type="button" class="button secondary" data-food-edit="light">عشاء خفيف دون طبخ</button>':''}</div><p id="mealPlanTotals" class="notice" aria-live="polite"></p><p id="mealPlanError" class="danger" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary" data-food-edit="close">إلغاء</button><button class="button">حفظ الوجبة والخطة</button></div></form>`;updateMealTotals();$('#mealPlanForm').onsubmit=e=>{e.preventDefault();try{if(activeProfile!==mealDraft.profile||JSON.stringify(data.nutrition.plan||null)!==mealDraft.fingerprint)throw Error('تم تحديث الخطة أثناء التعديل. أغلق النافذة وافتحها مجددًا.');if(!m.items.length)throw Error('أضف طعامًا واحدًا على الأقل.');if(m.items.some(x=>!Number.isFinite(x.g)||x.g<1||x.g>2000||!allowed.includes(x.key)))throw Error('راجع الكميات والحساسيات؛ أحد الأطعمة غير مناسب لاستبعاداتك.');const next=structuredClone(data);next.nutrition.plan=recalculateFoodPlan(mealDraft.plan);next.nutrition.plan.manuallyAdjusted=true;validate(next);if(commit(next,'تم حفظ المكونات وإعادة حساب إجماليات الوجبة واليوم'))foodPlanDialog.close()}catch(err){$('#mealPlanError').textContent=err.message}}}
function updateMealTotals(){if(!mealDraft)return;const m=mealDraft.plan.days[mealDraft.di].meals[mealDraft.mi],t=foodTotal(m.items);$('#mealPlanTotals').textContent=`${fmt(t.calories)} سعرة · بروتين ${fmt(t.protein)} غ · كارب ${fmt(t.carbs)} غ · دهون ${fmt(t.fat)} غ`}
foodPlanDialog.addEventListener('input',e=>{if(!mealDraft)return;const index=e.target.dataset.foodGrams;if(index!==undefined){mealDraft.plan.days[mealDraft.di].meals[mealDraft.mi].items[Number(index)].g=Number(e.target.value);updateMealTotals()}});
foodPlanDialog.addEventListener('change',e=>{const index=e.target.dataset.foodKey;if(index!==undefined){mealDraft.plan.days[mealDraft.di].meals[mealDraft.mi].items[Number(index)].key=e.target.value;updateMealTotals()}});
foodPlanDialog.addEventListener('click',e=>{if(!mealDraft)return;const m=mealDraft.plan.days[mealDraft.di].meals[mealDraft.mi],remove=e.target.closest('[data-food-remove]')?.dataset.foodRemove,a=e.target.closest('[data-food-edit]')?.dataset.foodEdit;if(remove!==undefined){m.items.splice(Number(remove),1);paintMealEditor()}if(a==='close')foodPlanDialog.close();if(a==='add'){m.items.push({key:'apple',g:100});paintMealEditor()}if(a==='light'){m.items=lightDinnerItems(data.nutrition.intake?.excluded||[],mealDraft.di);paintMealEditor()}});
window.renderNutritionPlan=()=>{const result=displayedFoodPlan(),p=result.plan;return nutritionTabs(true)+`<div class="daily-banner"><div><h2>ماذا آكل هذا الأسبوع؟</h2><p>خطة التغذية · عشاء خفيف جاهز للأكل</p></div><button class="button secondary" data-coach="setup">تعديل الهدف والاختيارات</button></div>${!p?`<div class="card"><p>${esc(result.error)}</p><button class="button" data-coach="setup">إكمال بياناتي</button></div>`:`<div class="card"><div class="card-head"><h2>${esc(p.goal)} · ${result.saved?'الخطة المحفوظة':'مسودة من قياس الجسم'}</h2><button class="button secondary" data-food-new>إنشاء مسودة جديدة</button></div><div class="body-metrics">${bodyMetric('الطاقة المستهدفة',p.targets.calories,'سعرة','الثبات التقديري '+fmt(p.maintenance))}${bodyMetric('البروتين',p.targets.protein,'غ','هدف يومي')}${bodyMetric('الكربوهيدرات',p.targets.carbs,'غ','هدف يومي')}${bodyMetric('الدهون',p.targets.fat,'غ','هدف يومي')}</div><p class="sub">${esc(p.method)}. الأهداف تقديرية. إجمالي كل يوم يعكس مكوناته الحالية؛ حذف الطعام أو استبداله لا يغيّر هدفك تلقائيًا.</p>${!result.saved?'<p class="notice">احفظ الخطة أو عدّل إحدى وجباتها لحفظها. ستظل وجباتك المأكولة في سجل مستقل.</p><button class="button" data-food-save>حفظ خطة التغذية</button>':''}</div>${p.days.map((d,di)=>`<details class="card coach-session" ${d.date===selected||di===0?'open':''}><summary>${pretty(d.date,{weekday:'long',day:'numeric',month:'long'})} · ${fmt(d.calories)} سعرة · ${fmt(d.protein)} غ بروتين</summary><p class="sub">الفرق عن هدف الطاقة: ${fmt(d.calories-p.targets.calories)} سعرة</p>${d.meals.map((m,mi)=>`<article class="record"><div class="record-head"><h3>${esc(m.name)} · ${esc(m.time)}</h3><div class="quick-buttons"><button class="button secondary" data-food-meal="${mi}" data-food-day="${di}">تعديل الأطعمة والكميات</button><button class="text-button" data-food-log="${mi}" data-food-day="${di}">تسجيل كوجبة مأكولة</button></div></div><p>${m.items.map(x=>`${esc(foods[x.key][0])} <b>${fmt(x.g)} غ</b>`).join(' + ')}</p><p class="sub">${fmt(m.calories)} سعرة · بروتين ${fmt(m.protein)} · كارب ${fmt(m.carbs)} · دهون ${fmt(m.fat)} غ</p></article>`).join('')}</details>`).join('')}`}`};
function saveFoodDraft(){const r=displayedFoodPlan();if(!r.plan)return;if(!r.saved&&(!r.n.healthConfirmed||Date.parse(today())-Date.parse(r.report.date)>90*86400000)){notify('أكد معلوماتك واختر قياسًا حديثًا قبل الحفظ.',true);openCoachSetup();return}const next=structuredClone(data);next.nutrition.plan=recalculateFoodPlan(structuredClone(r.plan));Object.assign(next.targets,r.plan.targets);validate(next);commit(next,'تم حفظ خطة التغذية وأهدافها')}
document.addEventListener('click',e=>{const edit=e.target.closest('[data-food-meal]'),log=e.target.closest('[data-food-log]');if(edit)openMealEditor(Number(edit.dataset.foodDay),Number(edit.dataset.foodMeal));if(log){const r=displayedFoodPlan(),day=r.plan?.days[Number(log.dataset.foodDay)],m=day?.meals[Number(log.dataset.foodLog)];if(m)openForm('meal',{...m,date:selected,food:m.items.map(x=>foods[x.key][0]+' '+x.g+' غ').join(' + ')},true)}if(e.target.closest('[data-food-save]'))saveFoodDraft();if(e.target.closest('[data-food-new]')){const m=currentBodyReport();if(!m){openCoachSetup();return}const r=coachDraft(m);if(!r.plan){notify(r.error,true);return}if(!r.n.healthConfirmed||Date.parse(today())-Date.parse(m.date)>90*86400000){notify('راجع بياناتك واختر قياسًا حديثًا قبل إنشاء الخطة.',true);openCoachSetup();return}if(data.nutrition.plan&&!confirm('إنشاء خطة جديدة بدل الوجبات المخططة وتعديلاتها الحالية؟'))return;const next=structuredClone(data);next.nutrition.plan=structuredClone(r.plan);validate(next);commit(next,'تم إنشاء خطة جديدة بعشاء خفيف')}});
